const body = $input.first().json.body ?? $input.first().json;
const text = String(body.text ?? '').slice(0, 4000).trim();
const filename = String(body.filename ?? '');
const documentId = body.documentId ?? null;

if (!text) throw new Error('No text provided');

return [{ json: { text, filename, documentId } }];

const item = $input.first().json;
const prev = $('Parse Input').first().json;

let raw = item.output ?? item.text ?? item.response ?? item.message?.content ?? item.content ?? '';
raw = String(raw).replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();

const firstBrace = raw.indexOf('{');
const lastBrace = raw.lastIndexOf('}');
if (firstBrace === -1 || lastBrace === -1) throw new Error('No JSON object in AI response: ' + raw.slice(0, 200));

const parsed = JSON.parse(raw.slice(firstBrace, lastBrace + 1));

return [{
  json: {
    documentId: prev.documentId,
    title:         parsed.title         || null,
    authorDisplay: parsed.authorDisplay || null,
    authors:       Array.isArray(parsed.authors) ? parsed.authors : (parsed.authorDisplay ? [parsed.authorDisplay] : []),
    year:          parsed.year          || null,
    journal:       parsed.journal       || null,
    doi:           parsed.doi           || null,
    metadataReliable: parsed.metadataReliable === true && !!(parsed.title && parsed.year && parsed.authorDisplay)
  }
}];
